{'code': "from qgis.PyQt.QtWidgets import QAction
mw = iface.mainWindow()
lyr = iface.activeLayer()
before = iface.mapCanvas().extent()
out = {'active_layer': lyr.name() if lyr else None, 'extent_before': before.toString()}
for a in mw.findChildren(QAction):
    if (a.objectName() or '') == 'mActionZoomToLayer':
        a.trigger()
        out['triggered'] = True
        break
after = iface.mapCanvas().extent()
out['extent_after'] = after.toString()
result = out"}

